"""Original Still disease and macrophage activation syndrome questions."""
from qbank_authoring import question,ref
rows=[]
S=ref('EULAR/PReS Still disease diagnosis and management: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11672000/')
H=ref('EULAR/ACR early HLH/MAS points to consider','https://pmc.ncbi.nlm.nih.gov/articles/PMC11017727/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A 32-year-old has daily fever spikes, an evanescent salmon-colored rash during fever, sore throat, inflammatory arthritis and neutrophilic leukocytosis. ANA and RF are negative. Which diagnosis is most likely after appropriate exclusion of mimics?', 'Adult-onset Still disease',[
 ('SLE','Leukopenia and an autoantibody-supported multisystem phenotype would be more typical than this neutrophilic fever-rash pattern.'),('Primary Sjogren disease','Sicca and its associated glandular/systemic pattern do not best fit.'),('Seropositive RA','The marked systemic fever/rash phenotype and absent supporting serology suggest a different inflammatory syndrome.')],
 'Recognize the systemic inflammatory phenotype','**Still disease can present with quotidian fever, evanescent rash, arthritis and neutrophilia.**',['Ferritin may be markedly elevated but is not diagnostic alone.','Infection, malignancy and other immune disorders need exclusion.'], '**Assess organ involvement and hyperinflammatory complications.**',['Check liver function, blood counts and evolving coagulation changes.','Do not treat a classification pattern as proof that sepsis or lymphoma is absent.'],[['Fever/rash timing','Useful pattern'],['Neutrophilia','Common clue'],['Ferritin','Supporting but nonspecific']],[S],style='clinical_scenario')

q('Which interpretation of markedly elevated ferritin in suspected Still disease is correct?', 'It supports hyperinflammation but is not uniquely specific for Still disease',[
 ('Ferritin above 1,000 establishes the diagnosis without further workup','Many infectious, malignant, hepatic and hyperinflammatory disorders can raise ferritin.'),('Normal transferrin saturation excludes every alternative inflammatory cause','This does not settle the systemic diagnosis.'),('Ferritin measures only iron overload and cannot rise with inflammation','It is also an acute-phase reactant.')],
 'Avoid a one-marker diagnosis','**Ferritin integrates inflammation, cell injury and iron biology.**',['The level and trend are useful when interpreted with the syndrome.','Extremely high values should also prompt consideration of HLH/MAS, severe infection and liver injury.'], '**Look for the pattern of organ dysfunction.**',['Assess cytopenias, triglycerides, fibrinogen and liver injury when HLH/MAS is suspected.','Continue etiological investigation rather than stopping at the ferritin result.'],[['High ferritin','Nonspecific inflammation clue'],['Falling counts/fibrinogen','Hyperinflammatory warning'],['Diagnosis','Clinical pattern plus exclusions']],[S,H])

q('According to current Still disease recommendations, which strategy can reduce prolonged glucocorticoid dependence?', 'Early IL-1 or IL-6 pathway inhibition in an appropriate patient',[
 ('Indefinite high-dose prednisone as the preferred universal maintenance plan','This adds substantial cumulative toxicity.'),('Hydroxychloroquine alone for every severe systemic presentation','This is not an adequate universal systemic Still strategy.'),('Waiting for fixed erosions before any steroid-sparing therapy','The aim is earlier control rather than delayed treatment after damage.')],
 'Use targeted control early enough to prevent chronic exposure','**Contemporary guidance supports early IL-1 or IL-6 inhibition for appropriate Still disease.**',['The target includes clinically inactive disease with glucocorticoid withdrawal when feasible.','Selection depends on phenotype, severity, access and safety.'], '**Reassess response and complications rather than simply extend prednisone.**',['Confirm the diagnosis and exclude infection.','Difficult-to-treat disease or recurrent severe MAS merits expert-center collaboration.'],[['IL-1/IL-6 therapy','Steroid-sparing strategy'],['Target','Inactive disease off GC when feasible'],['Poor response','Expert reassessment']],[S])

q('Which biological agent blocks the IL-1 receptor?', 'Anakinra',[
 ('Canakinumab','This neutralizes IL-1 beta rather than blocking the receptor.'),('Tocilizumab','This blocks the IL-6 receptor.'),('Emapalumab','This neutralizes interferon gamma.')],
 'Distinguish receptor blockade from cytokine neutralization','**Anakinra is an IL-1 receptor antagonist.**',['Its relatively short action can be useful in selected acute inflammatory settings.','Choice and dose depend on the disease, severity and renal function.'], '**Use the mechanism with a syndrome-specific treatment plan.**',['Screen and monitor for infection and cytopenias as appropriate.','A response supports pathway sensitivity but is not a unique diagnostic test.'],[['Anakinra','IL-1 receptor'],['Canakinumab','IL-1 beta'],['Tocilizumab','IL-6 receptor']],[S,H])

q('A patient with Still disease develops new dyspnea, hypoxemia and diffuse pulmonary abnormalities while joint symptoms are controlled. Which statement is correct?', 'Still-associated lung disease and other serious pulmonary causes require assessment despite controlled arthritis',[
 ('Quiet joints exclude a systemic complication','Organ activity and joint activity can diverge.'),('Every new infiltrate proves a medication allergy','Infection, inflammatory lung disease, edema and other causes need evaluation.'),('IL-1 or IL-6 treatment makes MAS impossible','MAS can occur during biologic treatment.')],
 'Do not infer global remission from one disease domain','**Still disease can have severe pulmonary and cardiac complications.**',['Biologic treatment can also blunt some inflammatory signals.','The pattern and tempo guide infection and inflammatory assessment.'], '**Evaluate oxygenation and organ threat promptly.**',['Use imaging, microbiology and cardiac studies as indicated.','Seek expert collaboration for severe or unusual disease.'],[['Joint control','Does not guarantee lung safety'],['New hypoxemia','Urgent organ assessment'],['Differential','Inflammation, infection and other mechanisms']],[S],style='clinical_scenario')

q('A patient with suspected Still disease has persistent focal lymphadenopathy and weight loss despite anti-inflammatory treatment. What is most appropriate?', 'Reassess for malignancy or infection and obtain appropriate tissue when indicated',[
 ('Assume every enlarged node is a benign Still manifestation','Persistent atypical findings can identify a mimic or coexisting disease.'),('Use ferritin reduction alone to exclude lymphoma','Ferritin can fall with treatment without establishing the cause.'),('Escalate immunosuppression without reviewing the diagnosis','This may obscure or worsen a serious alternative cause.')],
 'Keep the diagnostic hypothesis open when the course is atypical','**Still disease is a clinical diagnosis requiring careful exclusion of important mimics.**',['Lymphoma and infection can produce fever, nodes, rash and hyperferritinemia.','Treatment response is not uniquely specific.'], '**Choose tissue that can answer the suspected mechanism.**',['Preserve architecture and microbiology material when relevant.','Coordinate hematology/infectious disease assessment as the presentation warrants.'],[['Persistent focal node','Needs explanation'],['Treatment response','Not a definitive diagnostic test'],['Biopsy','Can reveal a mimic']],[S,H],style='clinical_scenario')

q('A Still disease patient develops unremitting fever, rapidly falling platelets, rising ferritin, hepatitis and falling fibrinogen. Which complication is most concerning?', 'Macrophage activation syndrome',[
 ('An uncomplicated articular flare','This typically does not explain the cytopenic/coagulopathic deterioration.'),('Iron deficiency alone','This does not account for hyperferritinemia, hepatitis and falling fibrinogen.'),('Isolated medication-related nausea','This does not explain the multisystem laboratory trajectory.')],
 'The trend can matter before a threshold is crossed','**MAS is a severe hyperinflammatory syndrome that can complicate Still disease.**',['A fall from high baseline platelets or fibrinogen can be significant even before the value is frankly low.','Infection can trigger or coexist with MAS.'], '**Act on the evolving syndrome and organ dysfunction.**',['Monitor counts, liver tests, ferritin, triglycerides, fibrinogen and coagulation.','Begin appropriate urgent treatment while investigating triggers.'],[['Ordinary inflammation','Often high platelets/fibrinogen'],['MAS evolution','Counts/fibrinogen can fall'],['Ferritin/hepatitis','Often worsen']],[S,H],style='clinical_scenario')

q('Why can ESR fall paradoxically during severe MAS despite clinical deterioration?', 'Fibrinogen consumption or reduction can lower ESR even as hyperinflammation worsens',[
 ('ESR is a direct quantitative ferritin assay','These are different measurements.'),('A falling ESR always proves successful treatment','The fibrinogen and clinical context can reverse this interpretation.'),('MAS cannot alter coagulation proteins','Coagulopathy and low fibrinogen are important features.')],
 'Interpret a marker through its biological determinants','**ESR depends partly on plasma proteins, including fibrinogen.**',['Low fibrinogen can make ESR less reflective of the inflammatory severity.','Follow the full trend rather than one reassuring number.'], '**Review coagulation and organ injury directly.**',['A falling platelet count and rising ferritin can be important warning changes.','Do not wait for every diagnostic criterion if the syndrome is rapidly progressing.'],[['ESR','Influenced by fibrinogen'],['Fibrinogen fall','Can reduce ESR'],['Clinical deterioration','Overrides isolated apparent marker improvement']],[H,S])

q('Which treatment principle is appropriate for severe Still-associated MAS?', 'Urgent high-dose glucocorticoids with selected additional therapy such as IL-1 blockade, ciclosporin or other specialist-directed agents',[
 ('NSAID monotherapy regardless of organ dysfunction','This is inadequate for severe MAS.'),('Wait for a marrow biopsy to show hemophagocytosis before any treatment','Hemophagocytosis can be absent and delay can be dangerous.'),('Treat only an infection trigger while ignoring worsening hyperinflammation','Both trigger and immune dysregulation may require simultaneous treatment.')],
 'Control hyperinflammation and the trigger in parallel','**Severe MAS needs urgent multidimensional care.**',['Treatment is tailored to trajectory, organ injury and the underlying disease.','Interferon-gamma-directed approaches can be relevant in selected settings under current guidance/labeling.'], '**Provide organ support and investigate infection.**',['Monitor response frequently and escalate if deterioration continues.','Immunomodulation does not replace appropriate antimicrobial therapy when infection is present.'],[['Inflammation','Urgent immune treatment'],['Trigger','Identify and treat'],['Organ failure','Support and close monitoring']],[S,H])

q('Which statement about MAS in a patient receiving IL-1 or IL-6 inhibitors is correct?', 'MAS can still occur and some usual fever or laboratory signals may be blunted',[
 ('Biologic treatment excludes MAS by definition','Treatment reduces risk/activity but does not make the syndrome impossible.'),('A normal CRP under tocilizumab reliably excludes MAS','IL-6 blockade can suppress CRP.'),('Only the total white count is needed to monitor deterioration','A broader trajectory of cytopenias, organ injury and coagulation is required.')],
 'Treatment changes the appearance of the syndrome','**Biologic-exposed MAS can have altered clinical or laboratory expression.**',['Clinical deterioration and changing trends need attention even if classic thresholds are not met.','Infection remains a potential trigger and differential.'], '**Compare with the patient’s recent baseline.**',['Review ferritin, platelets, fibrinogen, liver injury and other organ parameters.','Seek expert assessment for an atypical or rapidly evolving presentation.'],[['Biologic therapy','Does not exclude MAS'],['CRP/fever','May be blunted'],['Serial pattern','More informative than one value']],[S,H])

if __name__=='__main__':print(f'Autoinflammatory/HLH draft: {len(rows)} questions')
